              >
                <Briefcase className="w-6 h-6" />
                <span className="text-xs font-black uppercase tracking-widest">Assistant</span>
                {/* Visual Tooltip */}
                <div className="absolute -bottom-12 left-1/2 -translate-x-1/2 w-48 p-2 bg-[#1e293b] text-[9px] text-white rounded-lg opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none z-[110] text-center shadow-2xl border border-white/10 font-bold uppercase tracking-wider">
