            </div>
          </div>

          {/* Security */}
          <div className="space-y-4">
            <div className="flex items-center space-x-2 text-[10px] font-black uppercase tracking-[0.3em] text-slate-500">
              <Shield className="w-3 h-3" />
              <span>Privacy & Lock</span>
            </div>

            {!settings.passcode ? (
              <div className="space-y-4">
                {!showPinInput ? (
                  <button 
                    onClick={() => setShowPinInput(true)}
                    className="w-full flex items-center justify-center space-x-3 p-5 glass hover:bg-white/5 text-slate-300 rounded-3xl transition-all border-white/5 text-sm font-bold uppercase tracking-widest"
                  >
                    <Key className="w-4 h-4" />
                    <span>Enable Lock Screen</span>
                  </button>
                ) : (
                  <div className="flex items-center space-x-3 animate-[fadeIn_0.3s]">
                    <input 
                      type="text" 
                      maxLength={4}
                      value={pinInput}
                      onChange={(e) => setPinInput(e.target.value.replace(/\D/g, ''))}
                      placeholder="PIN"
                      className="flex-1 bg-white/5 border border-white/10 rounded-2xl p-4 text-center text-xl font-black tracking-[1em] text-white outline-none focus:border-pink-500 transition-colors"
                    />
                    <button 
                      onClick={handleSetPasscode}
                      className="p-4 bg-emerald-600 hover:bg-emerald-500 text-white rounded-2xl transition-all"
                    >
                      <Save className="w-6 h-6" />
                    </button>
                    <button 
                      onClick={() => { setShowPinInput(false); setPinInput(''); }}
                      className="p-4 bg-white/5 text-slate-500 rounded-2xl"
                    >
                      <X className="w-6 h-6" />
                    </button>
                  </div>
                )}
              </div>
            ) : (
              <div className="flex items-center justify-between p-5 glass rounded-3xl border-white/5">
                <div className="flex items-center space-x-3 text-emerald-400 text-xs font-black uppercase tracking-widest">
                  <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></div>
                  <span>Secure Mode Active</span>
                </div>
                <button 
                  onClick={handleRemovePasscode}
                  className="text-[10px] font-black uppercase tracking-widest text-red-500 hover:text-red-400 transition-all"
                >
                  Disable
                </button>
              </div>
            )}
          </div>

          {/* Flirt Meter */}
          {settings.personaMode === 'romantic' && (
            <div className="space-y-4">
               <div className="flex items-center space-x-2 text-[10px] font-black uppercase tracking-[0.3em] text-slate-500">
                 <Sparkles className="w-3 h-3" />
                 <span>Passion Intensity</span>
               </div>

               <div className="px-2 glass p-6 rounded-3xl border-white/5">
                 <input 
                   type="range" 
                   min="1" 
                   max="5" 
                   step="1"
                   value={settings.flirtLevel || 3}
                   onChange={handleFlirtChange}
                   className="w-full h-1 bg-slate-800 rounded-lg appearance-none cursor-pointer accent-pink-500"
                 />
                 <div className="flex justify-between mt-4 text-[10px] text-slate-600 font-black tracking-widest uppercase">
                   <span>Soft</span>
                   <span>Obsessed</span>
                 </div>
                 <div className="text-center mt-4 text-pink-400 font-black text-sm uppercase tracking-[0.2em] animate-pulse">
                   {getFlirtLabel(settings.flirtLevel || 3)}
                 </div>
               </div>
            </div>
          )}

          {/* Memory Bank */}
          <div className="space-y-4">
            <div className="flex items-center justify-between text-[10px] font-black uppercase tracking-[0.3em] text-slate-500">
              <div className="flex items-center space-x-2">
                <UserCheck className="w-3 h-3" />
                <span>Core Memory Bank</span>
                <span className="bg-pink-500/20 text-pink-400 px-2 py-0.5 rounded-full ml-1 border border-pink-500/20">{memoryCount}</span>
              </div>
              {memoryCount > 0 && (
                <button 
                  onClick={clearMemories}
                  className="text-red-500 hover:text-red-400 transition-all flex items-center space-x-1"
                >
                  <Trash2 className="w-2.5 h-2.5" />
                  <span>Forget All</span>
                </button>
              )}
            </div>

            <div className="space-y-3">
              <div className="flex space-x-2">
                <input 
                  type="text" 
                  value={newMemory}
                  onChange={(e) => setNewMemory(e.target.value)}
                  placeholder="e.g. My birthday is Dec 5th"
                  className="flex-1 glass border border-white/10 rounded-2xl px-4 py-3 text-sm text-slate-200 focus:border-pink-500 outline-none transition-all"
                  onKeyDown={(e) => e.key === 'Enter' && addMemory()}
                />
                <button 
                  onClick={addMemory}
                  className="p-3 premium-gradient rounded-2xl shadow-lg shadow-pink-500/20 text-white hover:scale-105 active:scale-95 transition-all"
                >
                  <Plus className="w-5 h-5" />
                </button>
              </div>

              <div className="space-y-2 max-h-48 overflow-y-auto custom-scrollbar pr-1">
                {memoryCount === 0 ? (
                  <div className="py-8 text-center glass border-dashed border-white/5 rounded-3xl text-[10px] font-black uppercase tracking-widest text-slate-600">
                    No memories saved yet
                  </div>
                ) : (
                  (settings.memories || []).map((mem, idx) => (
                    <div key={idx} className="flex items-center justify-between p-4 glass rounded-2xl border-white/5 group/mem animate-[messageIn_0.3s_ease-out]">
                      <span className="text-xs font-medium text-slate-300 leading-snug">{mem}</span>
                      <button 
                        onClick={() => removeMemory(idx)}
                        className="text-slate-600 hover:text-red-500 transition-all ml-4 p-1"
                      >
                        <Trash2 className="w-4 h-4" />
                      </button>
                    </div>
                  ))
                )}
              </div>
            </div>
          </div>

          <div className="pt-4 border-t border-white/5">
            <button 
              onClick={() => {
                if(window.confirm("This will erase ALL chats and reset your preferences. This action cannot be undone. Proceed?")) {
                  onClearAllData();
                }
              }}
              className="w-full flex items-center justify-center space-x-3 p-6 text-red-500 hover:bg-red-500/10 rounded-3xl transition-all border border-transparent hover:border-red-500/20 text-[10px] font-black uppercase tracking-[0.4em]"
            >
              <Trash2 className="w-4 h-4" />
              <span>Reset Entire App</span>
            </button>
          </div>
        </div>
      </div>
      <style>{`
        @keyframes messageIn { 
          from { opacity: 0; transform: scale(0.95) translateY(20px); } 
          to { opacity: 1; transform: scale(1) translateY(0); } 
        }
      `}</style>
    </div>
  );
};

