import { Send, Menu, Plus, Settings, Sparkles, User, Mic, Trash2, Image as ImageIcon, X, Volume2, VolumeX, Play, Square, History, Loader2, Heart, Share2, MoreHorizontal, Wand2, Search, Zap } from 'lucide-react';
import React, { useState, useRef, useEffect, useMemo } from 'react';
import { Message, Sender, ChatSession, AppSettings } from '../types';
import { INITIAL_GREETING } from '../constants';

interface ChatInterfaceProps {
  currentChatId: string | null;
  chats: ChatSession[];
  settings: AppSettings;
  onSendMessage: (text: string, attachment?: string, isImageGen?: boolean) => Promise<void>;
  onNewChat: () => void;
  onSelectChat: (id: string) => void;
  onDeleteChat: (id: string) => void;
  onOpenSettings: () => void;
  onPlayAudio: (text: string, msgId: string) => void;
  isLoading: boolean;
  playingMessageId: string | null;
  playbackProgress: number;
  audioVolume: number;
  onVolumeChange: (vol: number) => void;
}

const PAGE_SIZE = 20;

const ChatInterface: React.FC<ChatInterfaceProps> = ({
  currentChatId,
  chats,
  onSendMessage,
  onNewChat,
  onSelectChat,
  onDeleteChat,
  onOpenSettings,
  onPlayAudio,
  isLoading,
  playingMessageId,
  playbackProgress,
  audioVolume,
  onVolumeChange
}) => {
  const [inputText, setInputText] = useState('');
  const [searchQuery, setSearchQuery] = useState('');
  const [isSearchOpen, setIsSearchOpen] = useState(false);
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [displayLimit, setDisplayLimit] = useState(PAGE_SIZE);
  const [localIsSending, setLocalIsSending] = useState(false);
  const [showVolumeSlider, setShowVolumeSlider] = useState(false);
  const [isImageGenMode, setIsImageGenMode] = useState(false);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const messageContainerRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const searchInputRef = useRef<HTMLInputElement>(null);

  const activeChat = chats.find(c => c.id === currentChatId);
  const allMessages = activeChat ? activeChat.messages : [];

  const hasContent = inputText.trim().length > 0 || selectedImage !== null;
  const canSend = hasContent && !isLoading && !localIsSending;

  useEffect(() => {
    setDisplayLimit(PAGE_SIZE);
    setIsSearchOpen(false);
    setSearchQuery('');
  }, [currentChatId]);

  useEffect(() => {
    if (isSearchOpen && searchInputRef.current) {
      searchInputRef.current.focus();
    }
  }, [isSearchOpen]);

  const filteredMessages = useMemo(() => {
    if (!searchQuery.trim()) return allMessages;
    return allMessages.filter(m => 
      m.text.toLowerCase().includes(searchQuery.toLowerCase())
    );
  }, [allMessages, searchQuery]);

  const visibleMessages = useMemo(() => {
    if (searchQuery.trim()) return filteredMessages;
    return allMessages.slice(-displayLimit);
  }, [allMessages, filteredMessages, displayLimit, searchQuery]);

  const hasMore = !searchQuery.trim() && allMessages.length > displayLimit;
  const remainingCount = allMessages.length - displayLimit;

  const scrollToBottom = (behavior: ScrollBehavior = 'smooth') => {
    if (messagesEndRef.current && !searchQuery.trim()) {
      messagesEndRef.current.scrollIntoView({ behavior });
    }
  };

  useEffect(() => {
    if (allMessages.length > 0) {
       scrollToBottom('smooth');
    }
  }, [allMessages.length, isLoading, selectedImage]);

  useEffect(() => {
    if (currentChatId) {
      setTimeout(() => scrollToBottom('auto'), 50);
    }
  }, [currentChatId]);

  useEffect(() => {
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
      textareaRef.current.style.height = Math.min(textareaRef.current.scrollHeight, 120) + 'px';
    }
  }, [inputText]);

  const handleImageSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      const reader = new FileReader();
      reader.onloadend = () => {
        setSelectedImage(reader.result as string);
        setIsImageGenMode(false); 
      };
      reader.readAsDataURL(file);
    }
  };

  const clearImage = () => {
    setSelectedImage(null);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleSend = async () => {
    const text = inputText.trim();
    if (!canSend) return;

    setLocalIsSending(true);
    const textToSend = text;
    const imageToSend = selectedImage || undefined;
    const genMode = isImageGenMode;

    setInputText('');
    setSelectedImage(null);
    setIsImageGenMode(false);
    if (fileInputRef.current) fileInputRef.current.value = '';
    if (textareaRef.current) textareaRef.current.style.height = 'auto';

    try {
      await onSendMessage(textToSend, imageToSend, genMode);
    } finally {
      setLocalIsSending(false);
      setTimeout(() => textareaRef.current?.focus(), 50);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  const handleChatDelete = (e: React.MouseEvent, id: string) => {
    e.preventDefault();
    e.stopPropagation();
    if (window.confirm("Ayo nanna muddu... Ee chat memory na delete madbeka? 🥺")) {
      onDeleteChat(id);
    }
  };

  const highlightText = (text: string, query: string) => {
    if (!query.trim()) return text;
    const parts = text.split(new RegExp(`(${query})`, 'gi'));
    return (
      <span>
        {parts.map((part, i) => 
          part.toLowerCase() === query.toLowerCase() 
            ? <mark key={i} className="bg-pink-500/40 text-white rounded px-0.5">{part}</mark> 
            : part
        )}
      </span>
    );
  };

  return (
    <div className="flex h-screen bg-[#020617] overflow-hidden relative font-['Outfit']">
      {/* Background Decor */}
      <div className="absolute top-0 left-0 w-full h-full overflow-hidden pointer-events-none z-0">
         <div className="absolute top-[-20%] left-[-10%] w-[60%] h-[60%] bg-pink-900/10 rounded-full blur-[160px] animate-pulse"></div>
         <div className="absolute bottom-[-20%] right-[-10%] w-[60%] h-[60%] bg-violet-900/10 rounded-full blur-[160px] animate-pulse" style={{animationDelay: '3s'}}></div>
         <div className="absolute inset-0 bg-grid-pattern opacity-[0.03]"></div>
      </div>

      {sidebarOpen && (
        <div 
          className="fixed inset-0 bg-black/60 z-[60] lg:hidden backdrop-blur-md transition-opacity duration-500"
          onClick={() => setSidebarOpen(false)}
        />
      )}

      {/* Sidebar */}
      <aside className={`fixed lg:static inset-y-0 left-0 z-[70] w-80 glass transform transition-all duration-500 ease-[cubic-bezier(0.16,1,0.3,1)] ${sidebarOpen ? 'translate-x-0 shadow-2xl' : '-translate-x-full lg:translate-x-0'} flex flex-col border-r border-white/5`}>
        <div className="p-8 flex items-center justify-between">
          <div className="flex items-center space-x-3 group">
            <div className="bg-gradient-to-tr from-pink-500 to-rose-500 p-2 rounded-2xl shadow-lg shadow-pink-500/20 group-hover:scale-110 transition-transform duration-500">
              <Sparkles className="w-5 h-5 text-white" />
            </div>
            <span className="font-black text-2xl tracking-tighter text-white">Arohi</span>
          </div>
          <button 
            onClick={onNewChat} 
            className="p-3 bg-white/5 hover:bg-white/10 rounded-2xl transition-all text-slate-300 hover:text-white hover:scale-110 active:scale-95 border border-white/5"
          >
            <Plus className="w-5 h-5" />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto px-4 py-2 space-y-1.5 custom-scrollbar">
           <div className="text-[10px] font-black text-slate-500 uppercase tracking-[0.3em] px-4 mb-4 mt-2">Private Memories</div>
           {chats.map((chat, idx) => (
             <div key={chat.id} className={`group relative animate-[messageInLeft_0.5s_ease-out_forwards]`} style={{animationDelay: `${idx * 0.05}s`}}>
               <button
                 onClick={() => {
                   onSelectChat(chat.id);
                   setSidebarOpen(false);
                 }}
                 className={`w-full text-left px-5 py-4 rounded-2xl transition-all duration-300 text-sm truncate flex items-center justify-between group ${chat.id === currentChatId ? 'bg-white/10 text-white border border-white/10 shadow-xl' : 'text-slate-400 hover:bg-white/5 hover:text-slate-100'}`}
               >
                 <span className="truncate font-medium pr-8">{chat.title}</span>
                 {chat.id === currentChatId && <div className="w-1.5 h-1.5 rounded-full bg-pink-500 shadow-[0_0_8px_#ec4899]"></div>}
               </button>
               <button 
                 onClick={(e) => handleChatDelete(e, chat.id)}
                 title="Delete Memory"
                 className="absolute right-3 top-1/2 -translate-y-1/2 p-2.5 text-slate-500 hover:text-red-500 hover:bg-red-500/10 rounded-xl opacity-0 group-hover:opacity-100 transition-all duration-200 z-[80]"
               >
                 <Trash2 className="w-4 h-4" />
               </button>
             </div>
           ))}
        </div>

        <div className="p-6">
          <button 
            onClick={onOpenSettings}
            className="flex items-center justify-center space-x-3 text-slate-400 hover:text-white transition-all w-full py-4 glass rounded-2xl border border-white/5 hover:bg-white/5"
          >
            <Settings className="w-5 h-5" />
            <span className="font-bold text-sm uppercase tracking-widest">Settings</span>
          </button>
        </div>
      </aside>

      {/* Main Content */}
