export default ChatInterface;

import { Send, Menu, Plus, Settings, Sparkles, User, Mic, Trash2, Image as ImageIcon, X, Volume2, VolumeX, Play, Square, History, Loader2, Heart, Share2, MoreHorizontal, Wand2, Search, Zap, MicOff, SearchCode, Volume1 } from 'lucide-react';
