  audioVolume: number;
  onVolumeChange: (vol: number) => void;
}

const PAGE_SIZE = 20;

const ChatInterface: React.FC<ChatInterfaceProps> = ({
  currentChatId,
  chats,
  onSendMessage,
  onNewChat,
  onSelectChat,
  onDeleteChat,
  onOpenSettings,
  onPlayAudio,
  isLoading,
  playingMessageId,
  playbackProgress,
  audioVolume,
  onVolumeChange
}) => {
  const [inputText, setInputText] = useState('');
  const [searchQuery, setSearchQuery] = useState('');
  const [isSearchOpen, setIsSearchOpen] = useState(false);
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [displayLimit, setDisplayLimit] = useState(PAGE_SIZE);
  const [localIsSending, setLocalIsSending] = useState(false);
  const [showVolumeSlider, setShowVolumeSlider] = useState(false);
  const [isImageGenMode, setIsImageGenMode] = useState(false);
  const [isListening, setIsListening] = useState(false);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const messageContainerRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const searchInputRef = useRef<HTMLInputElement>(null);
  const recognitionRef = useRef<any>(null);

  const activeChat = chats.find(c => c.id === currentChatId);
  const allMessages = activeChat ? activeChat.messages : [];

  const hasContent = inputText.trim().length > 0 || selectedImage !== null;
  const canSend = hasContent && !isLoading && !localIsSending;

  // Find the message currently playing to show captions
  const playingMessage = useMemo(() => {
    if (!playingMessageId) return null;
    return allMessages.find(m => m.id === playingMessageId);
  }, [playingMessageId, allMessages]);

  useEffect(() => {
    setDisplayLimit(PAGE_SIZE);
  }, [currentChatId]);

  useEffect(() => {
    if (isSearchOpen && searchInputRef.current) {
      searchInputRef.current.focus();
    }
  }, [isSearchOpen]);

  const filteredMessages = useMemo(() => {
    if (!searchQuery.trim()) return allMessages;
    const q = searchQuery.toLowerCase();
    return allMessages.filter(m => m.text.toLowerCase().includes(q));
  }, [allMessages, searchQuery]);

  const visibleMessages = useMemo(() => {
    if (searchQuery.trim()) return filteredMessages;
    return allMessages.slice(-displayLimit);
  }, [allMessages, filteredMessages, displayLimit, searchQuery]);

  const hasMore = !searchQuery.trim() && allMessages.length > displayLimit;

  const chatHasMatch = (chat: ChatSession) => {
    if (!searchQuery.trim()) return false;
    const q = searchQuery.toLowerCase();
    return chat.title.toLowerCase().includes(q) || 
           chat.messages.some(m => m.text.toLowerCase().includes(q));
  };

  const scrollToBottom = (behavior: ScrollBehavior = 'smooth') => {
    if (messagesEndRef.current && !searchQuery.trim()) {
      messagesEndRef.current.scrollIntoView({ behavior });
    }
  };

  useEffect(() => {
    if (allMessages.length > 0) {
       scrollToBottom('smooth');
    }
  }, [allMessages.length, isLoading, selectedImage]);

  useEffect(() => {
    if (currentChatId) {
      setTimeout(() => scrollToBottom('auto'), 50);
    }
  }, [currentChatId]);

  useEffect(() => {
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
      textareaRef.current.style.height = Math.min(textareaRef.current.scrollHeight, 120) + 'px';
    }
  }, [inputText]);

  // Speech Recognition Setup
  useEffect(() => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (SpeechRecognition) {
      recognitionRef.current = new SpeechRecognition();
      recognitionRef.current.continuous = false;
      recognitionRef.current.interimResults = false;
      recognitionRef.current.lang = 'en-IN';

      recognitionRef.current.onresult = (event: any) => {
        const transcript = event.results[0][0].transcript;
        setInputText(prev => (prev ? `${prev} ${transcript}` : transcript));
        setIsListening(false);
      };

      recognitionRef.current.onerror = () => setIsListening(false);
      recognitionRef.current.onend = () => setIsListening(false);
    }

    return () => {
      if (recognitionRef.current) recognitionRef.current.stop();
    };
  }, []);

  const toggleListening = () => {
    if (!recognitionRef.current) {
      alert("Ayo bangara, your browser doesn't support voice typing. 🥺");
      return;
    }
    if (isListening) recognitionRef.current.stop();
    else {
      setIsListening(true);
      recognitionRef.current.start();
    }
  };

  const handleImageSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      const reader = new FileReader();
      reader.onloadend = () => {
        setSelectedImage(reader.result as string);
        setIsImageGenMode(false); 
      };
      reader.readAsDataURL(file);
    }
  };

  const clearImage = () => {
    setSelectedImage(null);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleSend = async () => {
    const text = inputText.trim();
    if (!canSend) return;

    setLocalIsSending(true);
    const textToSend = text;
    const imageToSend = selectedImage || undefined;
    const genMode = isImageGenMode;

    setInputText('');
    setSelectedImage(null);
    setIsImageGenMode(false);
    if (fileInputRef.current) fileInputRef.current.value = '';
    if (textareaRef.current) textareaRef.current.style.height = 'auto';

    try {
      await onSendMessage(textToSend, imageToSend, genMode);
    } finally {
      setLocalIsSending(false);
      setTimeout(() => textareaRef.current?.focus(), 50);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  const handleChatDelete = (e: React.MouseEvent, id: string) => {
    e.preventDefault();
    e.stopPropagation();
    if (window.confirm("Ayo nanna muddu... Ee chat memory na delete madbeka? 🥺")) {
      onDeleteChat(id);
    }
  };

  const highlightText = (text: string, query: string) => {
    if (!query.trim()) return <span>{text}</span>;
    const escapedQuery = query.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const parts = text.split(new RegExp(`(${escapedQuery})`, 'gi'));
    return (
      <span>
        {parts.map((part, i) => 
          part.toLowerCase() === query.toLowerCase() 
            ? <mark key={i} className="bg-pink-500/30 text-pink-200 border-b border-pink-500/50 rounded-sm px-0.5 font-bold transition-all duration-300">{part}</mark> 
            : part
        )}
      </span>
    );
  };

  return (
    <div className="flex h-screen bg-[#020617] overflow-hidden relative font-['Outfit']">
      {/* Background Decor */}
      <div className="absolute top-0 left-0 w-full h-full overflow-hidden pointer-events-none z-0">
         <div className="absolute top-[-20%] left-[-10%] w-[60%] h-[60%] bg-pink-900/10 rounded-full blur-[160px] animate-pulse"></div>
         <div className="absolute bottom-[-20%] right-[-10%] w-[60%] h-[60%] bg-violet-900/10 rounded-full blur-[160px] animate-pulse" style={{animationDelay: '3s'}}></div>
         <div className="absolute inset-0 bg-grid-pattern opacity-[0.03]"></div>
      </div>

      {sidebarOpen && (
        <div 
          className="fixed inset-0 bg-black/60 z-[60] lg:hidden backdrop-blur-md transition-opacity duration-500"
          onClick={() => setSidebarOpen(false)}
        />
      )}

      {/* Sidebar */}
      <aside className={`fixed lg:static inset-y-0 left-0 z-[70] w-80 glass transform transition-all duration-500 ease-[cubic-bezier(0.16,1,0.3,1)] ${sidebarOpen ? 'translate-x-0 shadow-2xl' : '-translate-x-full lg:translate-x-0'} flex flex-col border-r border-white/5`}>
        <div className="p-8 flex items-center justify-between">
          <div className="flex items-center space-x-3 group">
            <div className="bg-gradient-to-tr from-pink-500 to-rose-500 p-2 rounded-2xl shadow-lg shadow-pink-500/20 group-hover:scale-110 transition-transform duration-500">
              <Sparkles className="w-5 h-5 text-white" />
            </div>
            <span className="font-black text-2xl tracking-tighter text-white">Arohi</span>
          </div>
          <button 
            onClick={onNewChat} 
            className="p-3 bg-white/5 hover:bg-white/10 rounded-2xl transition-all text-slate-300 hover:text-white hover:scale-110 active:scale-95 border border-white/5"
          >
            <Plus className="w-5 h-5" />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto px-4 py-2 space-y-1.5 custom-scrollbar">
           <div className="text-[10px] font-black text-slate-500 uppercase tracking-[0.3em] px-4 mb-4 mt-2">Private Memories</div>
           {chats.map((chat, idx) => {
             const matched = chatHasMatch(chat);
             return (
               <div key={chat.id} className={`group relative animate-[messageInLeft_0.5s_ease-out_forwards]`} style={{animationDelay: `${idx * 0.05}s`}}>
                 <button
                   onClick={() => {
                     onSelectChat(chat.id);
                     setSidebarOpen(false);
                   }}
                   className={`w-full text-left px-5 py-4 rounded-2xl transition-all duration-300 text-sm truncate flex flex-col group ${chat.id === currentChatId ? 'bg-white/10 text-white border border-white/10 shadow-xl' : 'text-slate-400 hover:bg-white/5 hover:text-slate-100'}`}
                 >
                   <div className="flex items-center justify-between w-full">
                     <span className="truncate font-medium pr-8">{chat.title}</span>
                     {chat.id === currentChatId && <div className="w-1.5 h-1.5 rounded-full bg-pink-500 shadow-[0_0_8px_#ec4899]"></div>}
                   </div>
                   {matched && (
                     <div className="mt-1 flex items-center space-x-1.5 text-[9px] font-black uppercase tracking-widest text-pink-400 animate-pulse">
                       <SearchCode className="w-3 h-3" />
                       <span>Match Found</span>
                     </div>
                   )}
                 </button>
                 <button 
                   onClick={(e) => handleChatDelete(e, chat.id)}
                   title="Delete Memory"
                   className="absolute right-3 top-1/2 -translate-y-1/2 p-2.5 text-slate-500 hover:text-red-500 hover:bg-red-500/10 rounded-xl opacity-0 group-hover:opacity-100 transition-all duration-200 z-[80]"
                 >
                   <Trash2 className="w-4 h-4" />
                 </button>
               </div>
             );
           })}
        </div>

        <div className="p-6">
          <button 
            onClick={onOpenSettings}
            className="flex items-center justify-center space-x-3 text-slate-400 hover:text-white transition-all w-full py-4 glass rounded-2xl border border-white/5 hover:bg-white/5"
          >
            <Settings className="w-5 h-5" />
            <span className="font-bold text-sm uppercase tracking-widest">Settings</span>
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col h-full relative z-10 transition-all duration-500">
        {/* Header */}
        <header className="h-20 glass border-b border-white/5 flex items-center px-6 md:px-10 justify-between z-[50] sticky top-0">
          <div className="flex items-center space-x-4 flex-1">
            <button onClick={() => setSidebarOpen(true)} className="lg:hidden text-slate-300 p-2 hover:bg-white/5 rounded-xl transition-all">
              <Menu className="w-6 h-6" />
            </button>
            {!isSearchOpen ? (
              <div className="flex items-center space-x-3">
                <div className="relative">
                  <div className="w-10 h-10 rounded-2xl bg-gradient-to-tr from-pink-500 to-rose-600 flex items-center justify-center shadow-lg shadow-pink-500/20">
                    <Heart className="w-5 h-5 text-white fill-white/20" />
                  </div>
                  <div className="absolute -bottom-1 -right-1 w-3.5 h-3.5 bg-emerald-500 border-4 border-[#020617] rounded-full"></div>
                </div>
                <div className="hidden sm:block">
                  <div className="flex items-center space-x-2">
                    <h2 className="font-black text-lg text-white tracking-tight">Arohi</h2>
                    <span className="flex items-center px-2 py-0.5 bg-emerald-500/10 border border-emerald-500/20 rounded-full text-[8px] font-black text-emerald-400 uppercase tracking-widest">
                      <Zap className="w-2 h-2 mr-1 fill-emerald-400" /> Ultra Fast
                    </span>
                  </div>
                  <div className="flex items-center space-x-1.5">
                    <span className="text-[9px] font-black uppercase tracking-[0.2em] text-emerald-400/80">Loving You Always</span>
                  </div>
                </div>
              </div>
            ) : (
              <div className="flex-1 max-w-md animate-[messageIn_0.2s_ease-out]">
                <div className="relative flex items-center">
                  <Search className="absolute left-4 w-4 h-4 text-slate-500" />
                  <input 
                    ref={searchInputRef}
                    type="text"
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    placeholder="Search messages..."
                    className="w-full bg-white/5 border border-white/10 rounded-2xl py-2.5 pl-11 pr-10 text-sm text-white focus:outline-none focus:border-pink-500/50 transition-all"
                  />
                  <button 
                    onClick={() => { setIsSearchOpen(false); setSearchQuery(''); }}
                    className="absolute right-2 p-1.5 text-slate-500 hover:text-white transition-all"
                  >
                    <X className="w-4 h-4" />
                  </button>
                </div>
              </div>
            )}
          </div>

          <div className="flex items-center space-x-2 md:space-x-4 ml-4">
            {!isSearchOpen && (
              <button 
                onClick={() => setIsSearchOpen(true)}
                className={`p-3 rounded-2xl transition-all ${searchQuery.trim() ? 'bg-pink-500 text-white shadow-lg' : 'text-slate-400 hover:text-white hover:bg-white/5'}`}
                title="Search conversation"
              >
                <Search className="w-5 h-5" />
              </button>
            )}

            <div className="relative group/vol">
              <button 
                onClick={() => setShowVolumeSlider(!showVolumeSlider)}
                className="p-3 text-slate-400 hover:text-white hover:bg-white/5 rounded-2xl transition-all"
              >
                {audioVolume === 0 ? <VolumeX className="w-5 h-5" /> : <Volume2 className="w-5 h-5" />}
              </button>
              {showVolumeSlider && (
                <div className="absolute top-full right-0 mt-2 p-4 glass border-white/10 rounded-2xl shadow-2xl z-[100] w-48 animate-[messageIn_0.2s_ease-out]">
                  <div className="flex items-center space-x-3">
                     <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Vol</span>
                     <input 
                      type="range" 
                      min="0" 
                      max="1" 
                      step="0.01" 
                      value={audioVolume}
                      onChange={(e) => onVolumeChange(parseFloat(e.target.value))}
                      className="flex-1 h-1 bg-slate-800 rounded-lg appearance-none cursor-pointer accent-pink-500"
                     />
                     <span className="text-[10px] font-black text-pink-400 w-8">{Math.round(audioVolume * 100)}%</span>
                  </div>
                </div>
              )}
            </div>
            <button className="p-3 text-slate-400 hover:text-white hover:bg-white/5 rounded-2xl transition-all"><MoreHorizontal className="w-5 h-5"/></button>
          </div>
        </header>

        {/* Messages */}
        <div 
          ref={messageContainerRef}
          className="flex-1 overflow-y-auto p-4 md:p-10 space-y-8 scroll-smooth custom-scrollbar"
        >
          {searchQuery.trim() && filteredMessages.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-center space-y-4 animate-[fadeIn_0.5s_ease-out]">
              <Search className="w-12 h-12 text-slate-700" />
              <div className="text-slate-500 text-sm">No results found for "{searchQuery}"</div>
              <button 
                onClick={() => setSearchQuery('')}
                className="text-pink-400 text-xs font-black uppercase tracking-widest hover:underline"
              >
                Clear Search
              </button>
            </div>
          ) : allMessages.length === 0 ? (
             <div className="h-full flex flex-col items-center justify-center text-center space-y-8 animate-[fadeIn_1s_ease-out_forwards]">
                <div className="relative group">
                  <div className="absolute inset-0 bg-pink-500 blur-[80px] opacity-20 rounded-full group-hover:opacity-40 transition-opacity duration-1000"></div>
                  <div className="w-24 h-24 glass rounded-[2.5rem] flex items-center justify-center shadow-2xl border-white/10 group-hover:scale-110 transition-transform duration-700">
                    <Heart className="w-10 h-10 text-pink-400 drop-shadow-[0_0_15px_rgba(236,72,153,0.5)] animate-pulse" />
                  </div>
                </div>
                <div className="space-y-3 px-6">
                  <h3 className="text-2xl font-black text-white tracking-tight">Arohi</h3>
                  <p className="text-slate-400 max-w-xs mx-auto text-sm leading-relaxed font-medium">"{INITIAL_GREETING}"</p>
                  <p className="text-[10px] text-slate-600 font-black uppercase tracking-[0.2em]">Powered by Arohi Engine • Faster than Ever</p>
                </div>
             </div>
          ) : (
            <>
              {hasMore && (
                <div className="flex justify-center py-4">
                  <button 
                    onClick={() => {}} 
                    className="flex items-center space-x-3 px-8 py-3 glass hover:bg-white/5 border border-white/5 rounded-full text-slate-400 hover:text-pink-300 text-xs font-black uppercase tracking-widest transition-all shadow-xl active:scale-95"
                  >
                    <History className="w-4 h-4" />
                    <span>Retrieve Older Memories</span>
                  </button>
                </div>
              )}

              {visibleMessages.map((msg, idx) => {
                const isUser = msg.sender === Sender.User;
                const isPlaying = playingMessageId === msg.id;

                return (
                  <div 
                    key={msg.id} 
                    className={`flex w-full ${isUser ? 'justify-end' : 'justify-start'} group/msg animate-[messageIn_0.4s_cubic-bezier(0.16,1,0.3,1)_forwards]`}
                  >
                    <div className={`flex max-w-[90%] md:max-w-[75%] ${isUser ? 'flex-row-reverse' : 'flex-row'} items-end gap-4`}>
                      <div className={`flex-shrink-0 w-10 h-10 rounded-2xl flex items-center justify-center shadow-2xl transition-all duration-500 group-hover/msg:scale-110 ${isUser ? 'bg-gradient-to-br from-blue-500 to-cyan-600' : 'bg-gradient-to-br from-pink-500 to-rose-600'}`}>
                        {isUser ? <User className="w-5 h-5 text-white" /> : <Heart className="w-5 h-5 text-white fill-white/20" />}
                      </div>

                      <div className="flex flex-col space-y-2">
                        {msg.attachment && (
                          <div className={`overflow-hidden rounded-3xl border border-white/10 transition-all duration-700 group-hover/msg:shadow-[0_0_30px_rgba(236,72,153,0.2)] shadow-2xl group/img relative`}>
                            <img src={msg.attachment} alt="attachment" className="max-w-full md:max-w-md max-h-96 object-cover" />
                          </div>
                        )}
                        {msg.text && (
                          <div className={`relative p-5 md:p-6 rounded-[2rem] text-[15px] md:text-[17px] leading-relaxed whitespace-pre-wrap shadow-2xl border transition-all duration-500 ${
                            isUser 
                              ? 'bg-blue-600 text-white rounded-br-none border-white/10' 
                              : 'glass text-slate-100 rounded-bl-none border-white/5'
                          } ${isPlaying ? 'ring-2 ring-pink-500 ring-offset-4 ring-offset-[#020617] scale-[1.02] shadow-[0_0_40px_rgba(236,72,153,0.3)]' : ''}`}>
                            <div className="font-medium">
                              {searchQuery.trim() ? highlightText(msg.text, searchQuery) : msg.text}
                            </div>

                            {isPlaying && (
                              <div className="mt-4 w-full h-1.5 bg-white/10 rounded-full overflow-hidden">
                                <div 
                                  className="h-full bg-pink-500 shadow-[0_0_8px_#ec4899] transition-all duration-200"
                                  style={{ width: `${playbackProgress}%` }}
                                ></div>
                              </div>
                            )}

                            <div className="mt-4 flex justify-between items-center">
                              <div className="text-[10px] font-black uppercase tracking-widest text-pink-400/60">
                                {isPlaying ? (isUser ? 'Echoing...' : 'Whispering...') : ''}
                              </div>
                              <button 
                                onClick={() => onPlayAudio(msg.text, msg.id)}
                                title="Voice Replay"
                                className={`p-2.5 rounded-full transition-all duration-300 flex items-center space-x-2 ${isPlaying ? 'bg-pink-500 text-white shadow-lg shadow-pink-500/40 animate-pulse' : 'bg-white/5 text-slate-400 hover:text-pink-300 hover:bg-white/10'}`}
                              >
                                {isPlaying ? <Square className="w-4 h-4 fill-white" /> : <Volume1 className="w-4 h-4 ml-0.5" />}
                              </button>
                            </div>
                          </div>
                        )}
                        <div className={`text-[9px] font-black uppercase tracking-widest text-slate-600 px-2 ${isUser ? 'text-right' : 'text-left'}`}>
                          {new Date(msg.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                        </div>
                      </div>
                    </div>
                  </div>
                );
              })}
            </>
          )}

          {isLoading && (
            <div className="flex justify-start w-full animate-[messageInLeft_0.5s_ease-out]">
               <div className="flex items-end space-x-4">
                  <div className="w-10 h-10 rounded-2xl bg-gradient-to-br from-pink-500 to-rose-600 flex items-center justify-center animate-pulse shadow-xl shadow-pink-500/20">
                    <Heart className="w-5 h-5 text-white" />
                  </div>
                  <div className="glass px-6 py-5 rounded-[2rem] rounded-bl-none border-white/5 shadow-2xl">
                    <div className="flex space-x-2 items-center">
                      <div className="w-2 h-2 bg-pink-500 rounded-full animate-[bounce_1s_infinite_0ms]"></div>
                      <div className="w-2 h-2 bg-pink-500 rounded-full animate-[bounce_1s_infinite_200ms]"></div>
                      <div className="w-2 h-2 bg-pink-500 rounded-full animate-[bounce_1s_infinite_400ms]"></div>
                    </div>
                  </div>
               </div>
            </div>
          )}
          <div ref={messagesEndRef} />
        </div>

        {/* Live Captions Overlay */}
        {playingMessage && (
          <div className="fixed bottom-32 left-1/2 -translate-x-1/2 w-[90%] max-w-2xl z-[100] animate-[messageIn_0.4s_cubic-bezier(0.16,1,0.3,1)]">
            <div className="glass bg-[#0f172a]/90 border-pink-500/40 rounded-3xl p-6 shadow-[0_0_50px_rgba(0,0,0,0.5)] border flex items-center space-x-4">
              <div className="flex-shrink-0 relative">
                <div className={`w-12 h-12 rounded-2xl flex items-center justify-center ${playingMessage.sender === Sender.User ? 'bg-blue-500' : 'bg-pink-500'} shadow-lg`}>
                  {playingMessage.sender === Sender.User ? <User className="w-6 h-6 text-white" /> : <Heart className="w-6 h-6 text-white" />}
                </div>
                <div className="absolute -top-1 -right-1 flex space-x-1">
                  <div className="w-2 h-2 bg-pink-500 rounded-full animate-ping"></div>
                </div>
              </div>
              <div className="flex-1 overflow-hidden">
                <div className="text-[10px] font-black text-pink-400 uppercase tracking-widest mb-1 flex items-center justify-between">
                  <span>Now Playing</span>
                  <span className="text-slate-500">{Math.round(playbackProgress)}%</span>
                </div>
                <p className="text-sm font-medium text-white line-clamp-2 italic leading-relaxed">
                  "{playingMessage.text}"
                </p>
              </div>
              <button 
                onClick={() => onPlayAudio('', playingMessage.id)}
                className="p-3 bg-white/5 hover:bg-white/10 text-slate-400 hover:text-white rounded-2xl transition-all"
              >
                <X className="w-5 h-5" />
              </button>
            </div>
          </div>
        )}

        {/* Input Area */}
        <div className="p-4 md:p-8 bg-gradient-to-t from-[#020617] via-[#020617]/95 to-transparent">
          <div className="max-w-4xl mx-auto">
            {selectedImage && (
               <div className="mb-4 relative inline-block animate-[messageInLeft_0.4s_ease-out]">
                 <div className="relative group">
                   <img src={selectedImage} alt="preview" className="h-32 rounded-3xl border border-pink-500/40 shadow-2xl object-cover" />
                   <button 
                     onClick={clearImage}
                     className="absolute -top-3 -right-3 bg-red-500 text-white rounded-full p-2 shadow-2xl border-4 border-[#020617]"
                   >
                     <X className="w-4 h-4" />
                   </button>
                 </div>
               </div>
            )}

            <div className={`relative flex items-end gap-3 glass border-white/10 rounded-[2.5rem] p-3 shadow-2xl transition-all duration-700 focus-within:bg-[#0f172a]/80 group/input ${isImageGenMode ? 'ring-2 ring-pink-500 bg-pink-900/10 border-pink-500/30 shadow-[0_0_30px_rgba(236,72,153,0.3)]' : 'focus-within:border-pink-500/40'}`}>
              <input type="file" accept="image/*" className="hidden" ref={fileInputRef} onChange={handleImageSelect} />

              <div className="flex items-center">
                <button onClick={() => fileInputRef.current?.click()} className="p-4 text-slate-400 hover:text-pink-400 hover:bg-pink-500/10 rounded-[1.5rem] transition-all">
                   <ImageIcon className="w-6 h-6" />
                </button>
                <button 
                  onClick={() => { setIsImageGenMode(!isImageGenMode); setSelectedImage(null); }}
                  className={`p-4 rounded-[1.5rem] transition-all ${isImageGenMode ? 'bg-pink-500 text-white shadow-lg' : 'text-slate-400 hover:text-pink-400 hover:bg-pink-500/10'}`}
                  title="Generate Magic Image"
                >
                   <Wand2 className={`w-6 h-6 ${isImageGenMode ? 'animate-pulse' : ''}`} />
                </button>
              </div>

              <textarea
                ref={textareaRef}
                rows={1}
                value={inputText}
                onChange={(e) => setInputText(e.target.value)}
                onKeyDown={handleKeyDown}
                placeholder={isImageGenMode ? "Describe nange yenu beku..." : "Talk to your Arohi..."}
                className={`flex-1 bg-transparent border-0 focus:ring-0 text-white placeholder-slate-600 resize-none py-4 text-lg font-medium scrollbar-hide transition-all`}
              />

              <div className="flex items-center">
                <button 
                  onClick={toggleListening}
                  className={`p-4 rounded-[1.5rem] transition-all ${isListening ? 'bg-red-500 text-white shadow-lg shadow-red-500/40 animate-pulse' : 'text-slate-400 hover:text-pink-400 hover:bg-pink-500/10'}`}
                  title={isListening ? "Listening..." : "Voice Input"}
