                   {isListening ? <MicOff className="w-6 h-6" /> : <Mic className="w-6 h-6" />}
                </button>

                <button 
                  onClick={handleSend}
                  disabled={!canSend}
                  className={`p-4 rounded-[1.5rem] transition-all duration-500 flex items-center justify-center min-w-[60px] min-h-[60px] ${
                    (hasContent && !isLoading) 
                      ? 'premium-gradient text-white shadow-xl hover:scale-110' 
                      : 'bg-white/5 text-slate-600 cursor-not-allowed'
                  }`}
                >
                  {(isLoading || localIsSending) ? <Loader2 className="w-6 h-6 animate-spin" /> : <Send className="w-6 h-6" />}
                </button>
              </div>
            </div>
            <div className="mt-4 text-[9px] text-center font-black uppercase tracking-[0.4em] text-slate-700">Arohi • Absolute Privacy • Created by mr_edigaa</div>
          </div>
        </div>
      </main>

      <style>{`
        @keyframes messageIn { 
          from { opacity: 0; transform: translateY(20px) scale(0.98); } 
          to { opacity: 1; transform: translateY(0) scale(1); } 
        }
        .scrollbar-hide::-webkit-scrollbar { display: none; }
      `}</style>
    </div>
  );
};

