import React, { useState, useEffect, useRef } from 'react';
import HomeHero from './components/HomeHero';
import ChatInterface from './components/ChatInterface';
import SettingsModal from './components/SettingsModal';
import LockScreen from './components/LockScreen';
import { ChatSession, AppSettings, Message, Sender } from './types';
import { sendMessageToGemini, generateSpeech } from './services/geminiService';

// Simple UUID generator polyfill
const generateId = () => Math.random().toString(36).substring(2, 15) + Math.random().toString(36).substring(2, 15);

const App: React.FC = () => {
  const [view, setView] = useState<'home' | 'chat'>('home');
  const [chats, setChats] = useState<ChatSession[]>([]);
  const [currentChatId, setCurrentChatId] = useState<string | null>(null);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [playingMessageId, setPlayingMessageId] = useState<string | null>(null);
  const [playbackProgress, setPlaybackProgress] = useState(0);
  const [audioVolume, setAudioVolume] = useState(1.0);
  const [isLocked, setIsLocked] = useState(false);

  const audioContextRef = useRef<AudioContext | null>(null);
  const gainNodeRef = useRef<GainNode | null>(null);
  const progressIntervalRef = useRef<number | null>(null);

  const [settings, setSettings] = useState<AppSettings>({
    memoryEnabled: true,
    theme: 'dark',
    flirtLevel: 3, 
    personaMode: 'romantic',
    memories: []
  });

  // Load from LocalStorage
  useEffect(() => {
    const savedChats = localStorage.getItem('arohi_chats');
    const savedSettings = localStorage.getItem('arohi_settings');
    const savedVolume = localStorage.getItem('arohi_volume');

    if (savedChats) {
      try {
        setChats(JSON.parse(savedChats));
      } catch (e) { console.error('Failed to parse chats', e); }
    }

    if (savedSettings) {
      try {
        const parsed = JSON.parse(savedSettings);
        const initialMemories = parsed.memories || (parsed.customMemory ? [parsed.customMemory] : []);

        setSettings(prev => ({ 
          ...prev, 
          ...parsed,
          memories: initialMemories,
          personaMode: parsed.personaMode || 'romantic'
        }));
        if (parsed.passcode) {
          setIsLocked(true);
        }
      } catch (e) { console.error('Failed to parse settings', e); }
    }

    if (savedVolume) {
      setAudioVolume(parseFloat(savedVolume));
    }
  }, []);

  // Save to LocalStorage
  useEffect(() => {
    localStorage.setItem('arohi_chats', JSON.stringify(chats));
  }, [chats]);

  useEffect(() => {
    localStorage.setItem('arohi_settings', JSON.stringify(settings));
  }, [settings]);

  useEffect(() => {
    localStorage.setItem('arohi_volume', audioVolume.toString());
    if (gainNodeRef.current) {
      gainNodeRef.current.gain.value = audioVolume;
    }
  }, [audioVolume]);

  const createNewChat = () => {
    const newChat: ChatSession = {
      id: generateId(),
      title: 'New Conversation',
      messages: [],
      createdAt: Date.now(),
      updatedAt: Date.now()
    };
    setChats(prev => [newChat, ...prev]);
    setCurrentChatId(newChat.id);
    setView('chat');
  };

  const deleteChat = (id: string) => {
    const updatedChats = chats.filter(c => c.id !== id);
    setChats(updatedChats);
    if (currentChatId === id) {
      if (updatedChats.length > 0) {
        setCurrentChatId(updatedChats[0].id);
      } else {
        setCurrentChatId(null);
        setView('home');
      }
    }
  };

  const handleSetReaction = (chatId: string, messageId: string, emoji: string) => {
    setChats(prev => prev.map(chat => {
      if (chat.id !== chatId) return chat;
      return {
        ...chat,
        messages: chat.messages.map(msg => {
          if (msg.id !== messageId) return msg;
          const currentReactions = msg.reactions || [];
          const hasReaction = currentReactions.includes(emoji);
          const newReactions = hasReaction 
            ? currentReactions.filter(r => r !== emoji)
            : [...currentReactions, emoji];
          return { ...msg, reactions: newReactions };
        })
      };
    }));
  };

  const handleStartChat = () => {
    if (chats.length > 0) {
      setCurrentChatId(chats[0].id);
      setView('chat');
    } else {
      createNewChat();
    }
  };

  const stopAudio = () => {
    if (progressIntervalRef.current) {
      window.clearInterval(progressIntervalRef.current);
      progressIntervalRef.current = null;
    }
    if (audioContextRef.current) {
      audioContextRef.current.close();
      audioContextRef.current = null;
    }
    setPlayingMessageId(null);
    setPlaybackProgress(0);
  };

  const playAudioData = async (base64Data: string, msgId: string) => {
    try {
      stopAudio();
      setPlayingMessageId(msgId);
      const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
      audioContextRef.current = audioContext;
      const cleanB64 = base64Data.replace(/^data:audio\/pcm;base64,/, "");
      const binaryString = atob(cleanB64);
      const len = binaryString.length;
      const bytes = new Uint8Array(len);
      for (let i = 0; i < len; i++) {
        bytes[i] = binaryString.charCodeAt(i);
      }
      const dataInt16 = new Int16Array(bytes.buffer);
      const audioBuffer = audioContext.createBuffer(1, dataInt16.length, 24000);
      const channelData = audioBuffer.getChannelData(0);
      for (let i = 0; i < dataInt16.length; i++) {
        channelData[i] = dataInt16[i] / 32768.0;
      }
      const gainNode = audioContext.createGain();
      gainNode.gain.value = audioVolume;
      gainNodeRef.current = gainNode;
      const source = audioContext.createBufferSource();
      source.buffer = audioBuffer;
      source.connect(gainNode);
      gainNode.connect(audioContext.destination);
      const duration = audioBuffer.duration;
      const startTime = audioContext.currentTime;
      source.onended = () => {
        if (playingMessageId === msgId) {
          stopAudio();
        }
      };
      progressIntervalRef.current = window.setInterval(() => {
        const elapsed = audioContext.currentTime - startTime;
        const progress = Math.min((elapsed / duration) * 100, 100);
        setPlaybackProgress(progress);
        if (progress >= 100) {
          if (progressIntervalRef.current) window.clearInterval(progressIntervalRef.current);
        }
      }, 100);
      source.start();
    } catch (e) {
      console.error("Playback error", e);
      stopAudio();
    }
  };

  const handlePlayAudio = async (text: string, msgId: string) => {
    if (playingMessageId === msgId) {
      stopAudio();
      return;
    }
    setIsLoading(true); 
    try {
      const audioData = await generateSpeech(text);
      if (audioData) {
        await playAudioData(audioData, msgId);
      }
    } finally {
      setIsLoading(false);
    }
  };

  const handleSendMessage = async (text: string, attachment?: string, isImageGen: boolean = false) => {
    if (!currentChatId) return;
    const userMsg: Message = {
      id: generateId(),
      text,
      sender: Sender.User,
      timestamp: Date.now(),
      attachment: attachment
    };
    setChats(prev => prev.map(c => {
      if (c.id === currentChatId) {
        const newTitle = c.messages.length === 0 
          ? (text.slice(0, 30) || (isImageGen ? "Creating Magic..." : "Image sent...")) 
          : c.title;
        return {
          ...c,
          title: newTitle,
          messages: [...c.messages, userMsg],
          updatedAt: Date.now()
        };
      }
      return c;
    }));
    setIsLoading(true);
    try {
      const activeChat = chats.find(c => c.id === currentChatId);
      const history = activeChat ? activeChat.messages : [];
      const response = await sendMessageToGemini(
        text, 
        attachment,
        history, 
        settings.memoryEnabled, 
        settings.flirtLevel || 3,
        settings.memories,
        settings.personaMode || 'romantic',
        isImageGen
      );
      const botMsg: Message = {
        id: generateId(),
        text: response.text,
        sender: Sender.Bot,
        timestamp: Date.now(),
        attachment: response.attachment
      };
      setChats(prev => prev.map(c => {
        if (c.id === currentChatId) {
          return {
            ...c,
            messages: [...c.messages, botMsg], 
            updatedAt: Date.now()
          };
        }
        return c;
      }));
    } catch (e) {
      console.error(e);
    } finally {
      setIsLoading(false);
    }
  };

  const clearAllData = () => {
    setChats([]);
    setCurrentChatId(null);
    setView('home');
    setIsSettingsOpen(false);
    localStorage.removeItem('arohi_chats');
    localStorage.removeItem('arohi_settings');
    setSettings({
      memoryEnabled: true,
      theme: 'dark',
      flirtLevel: 3, 
      personaMode: 'romantic',
      memories: []
    });
  };

  return (
    <div className="font-sans text-slate-200">
      {isLocked && settings.passcode && (
        <LockScreen 
          storedPin={settings.passcode} 
          onUnlock={() => setIsLocked(false)} 
        />
      )}
      {view === 'home' ? (
        <HomeHero onStartChat={handleStartChat} />
      ) : (
        <ChatInterface 
          currentChatId={currentChatId}
          chats={chats}
          settings={settings}
          onSendMessage={handleSendMessage}
          onNewChat={createNewChat}
          onSelectChat={setCurrentChatId}
          onDeleteChat={deleteChat}
          onOpenSettings={() => setIsSettingsOpen(true)}
          onPlayAudio={handlePlayAudio}
          onSetReaction={handleSetReaction}
          isLoading={isLoading}
          playingMessageId={playingMessageId}
          playbackProgress={playbackProgress}
          audioVolume={audioVolume}
          onVolumeChange={setAudioVolume}
        />
      )}
      <SettingsModal 
        isOpen={isSettingsOpen}
        onClose={() => setIsSettingsOpen(false)}
        settings={settings}
        onUpdateSettings={setSettings}
        onClearAllData={clearAllData}
      />
    </div>
  );
};

export default App;

import { Send, Menu, Plus, Settings, Sparkles, User, Mic, Trash2, Image as ImageIcon, X, Volume2, VolumeX, Play, Square, History, Loader2, Heart, Share2, MoreHorizontal, Wand2, Search, Zap, MicOff, SearchCode, Volume1, Smile } from 'lucide-react';
import React, { useState, useRef, useEffect, useMemo } from 'react';
import { Message, Sender, ChatSession, AppSettings } from '../types';
import { INITIAL_GREETING } from '../constants';

interface ChatInterfaceProps {
  currentChatId: string | null;
  chats: ChatSession[];
  settings: AppSettings;
  onSendMessage: (text: string, attachment?: string, isImageGen?: boolean) => Promise<void>;
  onNewChat: () => void;
  onSelectChat: (id: string) => void;
  onDeleteChat: (id: string) => void;
  onOpenSettings: () => void;
  onPlayAudio: (text: string, msgId: string) => void;
  onSetReaction: (chatId: string, messageId: string, emoji: string) => void;
  isLoading: boolean;
  playingMessageId: string | null;
  playbackProgress: number;
  audioVolume: number;
  onVolumeChange: (vol: number) => void;
}

const PAGE_SIZE = 20;
const REACTIONS = ['❤️', '😂', '👍', '🔥', '😮'];

const ChatInterface: React.FC<ChatInterfaceProps> = ({
  currentChatId,
  chats,
  onSendMessage,
  onNewChat,
  onSelectChat,
  onDeleteChat,
  onOpenSettings,
  onPlayAudio,
  onSetReaction,
  isLoading,
  playingMessageId,
  playbackProgress,
  audioVolume,
  onVolumeChange
}) => {
  const [inputText, setInputText] = useState('');
  const [searchQuery, setSearchQuery] = useState('');
  const [isSearchOpen, setIsSearchOpen] = useState(false);
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [displayLimit, setDisplayLimit] = useState(PAGE_SIZE);
  const [localIsSending, setLocalIsSending] = useState(false);
  const [showVolumeSlider, setShowVolumeSlider] = useState(false);
  const [isImageGenMode, setIsImageGenMode] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const [hoveredMessageId, setHoveredMessageId] = useState<string | null>(null);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const messageContainerRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const searchInputRef = useRef<HTMLInputElement>(null);
  const recognitionRef = useRef<any>(null);

  const activeChat = chats.find(c => c.id === currentChatId);
  const allMessages = activeChat ? activeChat.messages : [];

  const hasContent = inputText.trim().length > 0 || selectedImage !== null;
  const canSend = hasContent && !isLoading && !localIsSending;

  const playingMessage = useMemo(() => {
    if (!playingMessageId) return null;
    return allMessages.find(m => m.id === playingMessageId);
  }, [playingMessageId, allMessages]);

  useEffect(() => {
    setDisplayLimit(PAGE_SIZE);
  }, [currentChatId]);

  useEffect(() => {
    if (isSearchOpen && searchInputRef.current) {
      searchInputRef.current.focus();
    }
  }, [isSearchOpen]);

  const filteredMessages = useMemo(() => {
    if (!searchQuery.trim()) return allMessages;
    const q = searchQuery.toLowerCase();
    return allMessages.filter(m => m.text.toLowerCase().includes(q));
  }, [allMessages, searchQuery]);

  const visibleMessages = useMemo(() => {
    if (searchQuery.trim()) return filteredMessages;
    return allMessages.slice(-displayLimit);
  }, [allMessages, filteredMessages, displayLimit, searchQuery]);

  const hasMore = !searchQuery.trim() && allMessages.length > displayLimit;

  const chatHasMatch = (chat: ChatSession) => {
    if (!searchQuery.trim()) return false;
    const q = searchQuery.toLowerCase();
    return chat.title.toLowerCase().includes(q) || 
           chat.messages.some(m => m.text.toLowerCase().includes(q));
  };

  const scrollToBottom = (behavior: ScrollBehavior = 'smooth') => {
    if (messagesEndRef.current && !searchQuery.trim()) {
      messagesEndRef.current.scrollIntoView({ behavior });
    }
  };

  useEffect(() => {
    if (allMessages.length > 0) {
       scrollToBottom('smooth');
    }
  }, [allMessages.length, isLoading, selectedImage]);

  useEffect(() => {
    if (currentChatId) {
      setTimeout(() => scrollToBottom('auto'), 50);
    }
  }, [currentChatId]);

  useEffect(() => {
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
      textareaRef.current.style.height = Math.min(textareaRef.current.scrollHeight, 120) + 'px';
    }
  }, [inputText]);

  useEffect(() => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (SpeechRecognition) {
      recognitionRef.current = new SpeechRecognition();
      recognitionRef.current.continuous = false;
      recognitionRef.current.interimResults = false;
      recognitionRef.current.lang = 'en-IN';
      recognitionRef.current.onresult = (event: any) => {
        const transcript = event.results[0][0].transcript;
        setInputText(prev => (prev ? `${prev} ${transcript}` : transcript));
        setIsListening(false);
      };
      recognitionRef.current.onerror = () => setIsListening(false);
      recognitionRef.current.onend = () => setIsListening(false);
    }
    return () => {
      if (recognitionRef.current) recognitionRef.current.stop();
    };
  }, []);

  const toggleListening = () => {
    if (!recognitionRef.current) {
      alert("Ayo bangara, your browser doesn't support voice typing. 🥺");
      return;
    }
    if (isListening) recognitionRef.current.stop();
    else {
      setIsListening(true);
      recognitionRef.current.start();
    }
  };

  const handleImageSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      const reader = new FileReader();
      reader.onloadend = () => {
        setSelectedImage(reader.result as string);
        setIsImageGenMode(false); 
      };
      reader.readAsDataURL(file);
    }
  };

  const clearImage = () => {
    setSelectedImage(null);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleSend = async () => {
    const text = inputText.trim();
    if (!canSend) return;
    setLocalIsSending(true);
    const textToSend = text;
    const imageToSend = selectedImage || undefined;
    const genMode = isImageGenMode;
    setInputText('');
    setSelectedImage(null);
    setIsImageGenMode(false);
    if (fileInputRef.current) fileInputRef.current.value = '';
    if (textareaRef.current) textareaRef.current.style.height = 'auto';
    try {
      await onSendMessage(textToSend, imageToSend, genMode);
    } finally {
      setLocalIsSending(false);
      setTimeout(() => textareaRef.current?.focus(), 50);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  const handleChatDelete = (e: React.MouseEvent, id: string) => {
    e.preventDefault();
    e.stopPropagation();
    if (window.confirm("Ayo nanna muddu... Ee chat memory na delete madbeka? 🥺")) {
      onDeleteChat(id);
    }
  };

  const highlightText = (text: string, query: string) => {
    if (!query.trim()) return <span>{text}</span>;
    const escapedQuery = query.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const parts = text.split(new RegExp(`(${escapedQuery})`, 'gi'));
    return (
      <span>
        {parts.map((part, i) => 
          part.toLowerCase() === query.toLowerCase() 
            ? <mark key={i} className="bg-pink-500/30 text-pink-200 border-b border-pink-500/50 rounded-sm px-0.5 font-bold transition-all duration-300">{part}</mark> 
            : part
        )}
      </span>
    );
  };

  return (
    <div className="flex h-screen bg-[#020617] overflow-hidden relative font-['Outfit']">
      <div className="absolute top-0 left-0 w-full h-full overflow-hidden pointer-events-none z-0">
         <div className="absolute top-[-20%] left-[-10%] w-[60%] h-[60%] bg-pink-900/10 rounded-full blur-[160px] animate-pulse"></div>
         <div className="absolute bottom-[-20%] right-[-10%] w-[60%] h-[60%] bg-violet-900/10 rounded-full blur-[160px] animate-pulse" style={{animationDelay: '3s'}}></div>
         <div className="absolute inset-0 bg-grid-pattern opacity-[0.03]"></div>
      </div>

      {sidebarOpen && (
        <div 
          className="fixed inset-0 bg-black/60 z-[60] lg:hidden backdrop-blur-md transition-opacity duration-500"
          onClick={() => setSidebarOpen(false)}
        />
      )}

      <aside className={`fixed lg:static inset-y-0 left-0 z-[70] w-80 glass transform transition-all duration-500 ease-[cubic-bezier(0.16,1,0.3,1)] ${sidebarOpen ? 'translate-x-0 shadow-2xl' : '-translate-x-full lg:translate-x-0'} flex flex-col border-r border-white/5`}>
        <div className="p-8 flex items-center justify-between">
          <div className="flex items-center space-x-3 group">
            <div className="bg-gradient-to-tr from-pink-500 to-rose-500 p-2 rounded-2xl shadow-lg shadow-pink-500/20 group-hover:scale-110 transition-transform duration-500">
              <Sparkles className="w-5 h-5 text-white" />
            </div>
            <span className="font-black text-2xl tracking-tighter text-white">Arohi</span>
          </div>
          <button 
            onClick={onNewChat} 
            className="p-3 bg-white/5 hover:bg-white/10 rounded-2xl transition-all text-slate-300 hover:text-white hover:scale-110 active:scale-95 border border-white/5"
          >
            <Plus className="w-5 h-5" />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto px-4 py-2 space-y-1.5 custom-scrollbar">
           <div className="text-[10px] font-black text-slate-500 uppercase tracking-[0.3em] px-4 mb-4 mt-2">Private Memories</div>
           {chats.map((chat, idx) => {
             const matched = chatHasMatch(chat);
             return (
               <div key={chat.id} className={`group relative animate-[messageInLeft_0.5s_ease-out_forwards]`} style={{animationDelay: `${idx * 0.05}s`}}>
                 <button
                   onClick={() => {
                     onSelectChat(chat.id);
                     setSidebarOpen(false);
                   }}
                   className={`w-full text-left px-5 py-4 rounded-2xl transition-all duration-300 text-sm truncate flex flex-col group ${chat.id === currentChatId ? 'bg-white/10 text-white border border-white/10 shadow-xl' : 'text-slate-400 hover:bg-white/5 hover:text-slate-100'}`}
